stimulus.text:
SELECT 사원명, 급여,
(㉠) AS 직전급여
FROM 사원;

SELECT e.사원명 AS 사원, m.사원명 AS 상사
FROM 사원 e JOIN 사원 m
ON (㉠);

SELECT *
FROM 사원 e, 부서 d
WHERE e.부서번호 = d.부서번호(+);

INSERT INTO 주문 ...;      -- 30건 삽입
TRUNCATE TABLE 임시로그;    -- (임시로그 테이블 비우기, DDL)
INSERT INTO 주문 ...;      -- 10건 추가 삽입
ROLLBACK;
SELECT COUNT(*) FROM 주문;

CREATE TABLE 주문 (
주문번호 NUMBER,
주문일자 DATE,
상품코드 CHAR(3)
);

SELECT 이름,
RANK() OVER (ORDER BY 점수 DESC) AS 순위
FROM 성적;

SELECT 사원명,
NVL2(보너스, 보너스 + 100, 0) AS 지급액
FROM 사원;

SELECT col FROM A
UNION ALL
SELECT col FROM B;

SELECT 사원번호
FROM 사원
WHERE 사원번호 NOT IN (SELECT 관리자번호 FROM 관리);

SELECT *
FROM 사원
WHERE 1 = 0;
